content.solution_code:
class MagicScroll {
  #chargeLevel;

  constructor() {
    this.#chargeLevel = 0;
  }

  recharge(amount) {
    if (amount > 0) {
      this.#chargeLevel += amount;
    }
  }

  castSpell(spellType) {
    const requiredCharge = 10;
    if (this.#chargeLevel >= requiredCharge) {
      this.#chargeLevel -= requiredCharge;
      return `Casting ${spellType}! Charge remaining: ${this.#chargeLevel}`;
    } else {
      return `Not enough charge to cast ${spellType}! Current charge: ${this.#chargeLevel}`;
    }
  }

  getChargeLevel() {
    return this.#chargeLevel;
  }
}

